#!/usr/bin/env node
/**
 * Patches BasketWeb.glb in place: replaces the web mesh's geometry with a
 * repaired version that has real thickness (a thin extruded shell) instead
 * of ~589 open gaps, so it no longer renders as solid black in the 3D
 * preview. Every other mesh, material, and node in the file is left
 * completely untouched -- this only appends new buffer data and repoints
 * one mesh's primitive at it.
 *
 * Usage:
 *   node fix-basket-web.js "C:\\Users\\bf218\\ballerzproseries\\public\\models\\BasketWeb.glb"
 *
 * Writes the result next to the input file as BasketWeb.fixed.glb (does
 * NOT overwrite your original -- rename/replace it yourself once you've
 * confirmed it looks right in the browser).
 */
const fs = require("fs");
const path = require("path");

const META = {"meshIdx": 6, "primIdx": 0, "vertCount": 10778, "faceCount": 19296, "posMin": [-0.3825682997703552, 0.0644531100988388, -0.1638183891773224], "posMax": [0.484130859375, 0.8969725966453552, 0.11059574782848358], "idxMin": 0, "idxMax": 10777};

const POS_B64 = "";
const NRM_B64 = "";
const UV_B64 = "";
const IDX_B64 = "";

function pad4(buf) {
  const rem = buf.length % 4;
  if (rem === 0) return buf;
  return Buffer.concat([buf, Buffer.alloc(4 - rem)]);
}

function main() {
  const srcPath = process.argv[2];
  if (!srcPath) {
    console.error("Usage: node fix-basket-web.js <path to BasketWeb.glb>");
    process.exit(1);
  }

  const fileBuf = fs.readFileSync(srcPath);

  const magic = fileBuf.toString("ascii", 0, 4);
  if (magic !== "glTF") throw new Error("Not a GLB file (bad magic).");
  const version = fileBuf.readUInt32LE(4);
  const totalLength = fileBuf.readUInt32LE(8);
  if (totalLength !== fileBuf.length) {
    throw new Error(`Header length (${totalLength}) doesn't match file size (${fileBuf.length}) -- refusing to touch a file that doesn't look like a clean GLB.`);
  }

  let offset = 12;
  const jsonChunkLen = fileBuf.readUInt32LE(offset);
  const jsonChunkType = fileBuf.readUInt32LE(offset + 4);
  if (jsonChunkType !== 0x4e4f534a) throw new Error("First chunk is not JSON.");
  const jsonBytes = fileBuf.subarray(offset + 8, offset + 8 + jsonChunkLen);
  const data = JSON.parse(jsonBytes.toString("utf8"));
  offset += 8 + jsonChunkLen;

  const binChunkLen = fileBuf.readUInt32LE(offset);
  const binChunkType = fileBuf.readUInt32LE(offset + 4);
  if (binChunkType !== 0x004e4942) throw new Error("Second chunk is not BIN.");
  let binBytes = Buffer.from(fileBuf.subarray(offset + 8, offset + 8 + binChunkLen));
  offset += 8 + binChunkLen;

  const mesh = data.meshes[META.meshIdx];
  if (!mesh) throw new Error(`No mesh at index ${META.meshIdx} -- this doesn't look like the expected file.`);
  const prim = mesh.primitives[META.primIdx];
  const origVertCount = data.accessors[prim.attributes.POSITION].count;
  console.log(`Found mesh ${META.meshIdx} ("${mesh.name || ""}") with ${origVertCount} vertices (pre-repair).`);

  const posBuf = Buffer.from(POS_B64, "base64");
  const nrmBuf = Buffer.from(NRM_B64, "base64");
  const uvBuf = Buffer.from(UV_B64, "base64");
  const idxBuf = Buffer.from(IDX_B64, "base64");

  function appendBuffer(raw) {
    binBytes = pad4(binBytes);
    const off = binBytes.length;
    binBytes = Buffer.concat([binBytes, raw]);
    return off;
  }

  const accStart = data.accessors.length;
  const bvStart = data.bufferViews.length;

  const posOffset = appendBuffer(posBuf);
  data.bufferViews.push({ buffer: 0, byteOffset: posOffset, byteLength: posBuf.length });
  data.accessors.push({
    bufferView: bvStart, componentType: 5126, count: META.vertCount, type: "VEC3",
    min: META.posMin, max: META.posMax,
  });
  const posAccIdx = accStart;

  const nrmOffset = appendBuffer(nrmBuf);
  data.bufferViews.push({ buffer: 0, byteOffset: nrmOffset, byteLength: nrmBuf.length });
  data.accessors.push({ bufferView: bvStart + 1, componentType: 5126, count: META.vertCount, type: "VEC3" });
  const nrmAccIdx = accStart + 1;

  const uvOffset = appendBuffer(uvBuf);
  data.bufferViews.push({ buffer: 0, byteOffset: uvOffset, byteLength: uvBuf.length });
  data.accessors.push({ bufferView: bvStart + 2, componentType: 5126, count: META.vertCount, type: "VEC2" });
  const uvAccIdx = accStart + 2;

  const idxOffset = appendBuffer(idxBuf);
  data.bufferViews.push({ buffer: 0, byteOffset: idxOffset, byteLength: idxBuf.length });
  data.accessors.push({
    bufferView: bvStart + 3, componentType: 5125, count: META.faceCount * 3, type: "SCALAR",
    min: [META.idxMin], max: [META.idxMax],
  });
  const idxAccIdx = accStart + 3;

  prim.attributes.POSITION = posAccIdx;
  prim.attributes.NORMAL = nrmAccIdx;
  prim.attributes.TEXCOORD_0 = uvAccIdx;
  prim.indices = idxAccIdx;

  binBytes = pad4(binBytes);
  data.buffers[0].byteLength = binBytes.length;

  let jsonOut = Buffer.from(JSON.stringify(data), "utf8");
  jsonOut = pad4Spaces(jsonOut);

  function pad4Spaces(buf) {
    const rem = buf.length % 4;
    if (rem === 0) return buf;
    return Buffer.concat([buf, Buffer.alloc(4 - rem, 0x20)]);
  }

  const jsonHeader = Buffer.alloc(8);
  jsonHeader.writeUInt32LE(jsonOut.length, 0);
  jsonHeader.writeUInt32LE(0x4e4f534a, 4);

  const binHeader = Buffer.alloc(8);
  binHeader.writeUInt32LE(binBytes.length, 0);
  binHeader.writeUInt32LE(0x004e4942, 4);

  const totalLen = 12 + jsonHeader.length + jsonOut.length + binHeader.length + binBytes.length;
  const header = Buffer.alloc(12);
  header.write("glTF", 0, "ascii");
  header.writeUInt32LE(2, 4);
  header.writeUInt32LE(totalLen, 8);

  const out = Buffer.concat([header, jsonHeader, jsonOut, binHeader, binBytes]);

  const dir = path.dirname(srcPath);
  const dstPath = path.join(dir, "BasketWeb.fixed.glb");
  fs.writeFileSync(dstPath, out);

  console.log(`Repaired mesh: ${META.vertCount} vertices, ${META.faceCount} faces (was ${origVertCount} vertices).`);
  console.log(`Wrote: ${dstPath}`);
  console.log("Your original file was NOT modified. Once you've confirmed BasketWeb.fixed.glb");
  console.log("looks right in the browser, rename it to BasketWeb.glb to replace the original.");
}

main();
